export function filterResources({category='For You',query='',selectedSubjects=subjects.slice(0,3).map(s=>s.name),saved=null}={}){const type={'PYQs':'PYQ','Books':'BOOK','Research':'RESEARCH','E-Resources':'E-RESOURCE'}[category];const q=query.trim().toLowerCase();return resources.filter(r=>(!type||r.type===type)&&(category!=='My Subjects'||selectedSubjects.includes(r.subject))&&(!saved||saved.includes(r.id))&&(!q||[r.title,r.subtitle,r.subject,r.code,r.description,r.provider].filter(Boolean).join(' ').toLowerCase().includes(q)));}
